import numpy as np


class DataStatistics2:
    def __init__(self, data):
        self._data = None
        self.data = data

    @property
    def data(self):
        return self._data

    @data.setter
    def data(self, value):
        self._data = np.array(value)

    def get_sum(self):
        return self._calculate_sum(self.data)

    def get_min(self):
        return self._calculate_min(self.data)

    def get_max(self):
        return self._calculate_max(self.data)

    def get_variance(self):
        return self._round_value(np.var(self.data), self.PRECISION)

    def get_std_deviation(self):
        return self._round_value(np.std(self.data), self.PRECISION)

    def get_correlation(self):
        return self._calculate_correlation(self.data)

    def _calculate_sum(self, data):
        return np.sum(data)

    def _calculate_min(self, data):
        return np.min(data)

    def _calculate_max(self, data):
        return np.max(data)

    def _round_value(self, value, precision):
        return round(value, precision)

    def _calculate_correlation(self, data):
        return np.corrcoef(data, rowvar=False)

    PRECISION = 2
